def transform(grid):
    bg = None
    best = -1
    for c in np.unique(grid):
        score = 0
        for row in grid:
            if np.all(row == c):
                score += grid.shape[1]
        for col in grid.T:
            if np.all(col == c):
                score += grid.shape[0]
        if score > best:
            best = score
            bg = c

    mask = grid != bg
    rows = np.where(mask.any(axis=1))[0]
    cols = np.where(mask.any(axis=0))[0]
    pattern = grid[rows.min():rows.max() + 1, cols.min():cols.max() + 1]

    h, w = pattern.shape
    out = np.empty_like(grid)
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            out[r, c] = pattern[r % h, (c + 1) % w]
    return out
